// Hand-written (NOT autogenerated). Guards the required '_id' field of Task,
// which tools/ulsdkbuild writes with TaskAdd_Id and reads with Get_Id.

package job

import (
	"bytes"
	"testing"

	"github.com/urbanlogiq/ulsdk/types/id"
)

func TestTaskUnderscoreIdRoundTrip(t *testing.T) {
	want := []byte{0x05, 0x00, 0x79, 0x31, 0x4d, 0x58, 0x42, 0x4e, 0xbe, 0x80, 0xe0, 0x80, 0xc2, 0x71, 0x5f, 0x7c}
	got, err := TaskFromBytes((&Task{Id: id.ObjectId{B: want}, Name: "t"}).ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got.Id.B, want) {
		t.Fatalf("id = %x, want %x", got.Id.B, want)
	}
	if got.Name != "t" {
		t.Fatalf("name = %q, want %q", got.Name, "t")
	}
}
